import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  texture as sampleTexture,
  positionLocal,
  normalLocal,
  vec3,
  mix,
  smoothstep,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Color,
    PointLight,
  } = THREE;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'features-list-row';

  const timelines = [];
  const primitiveCleanups = [];
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  let disposed = false;

  const colorVector = (value, fallback) => {
    const color = new Color(value ?? fallback);
    return vec3(color.r, color.g, color.b);
  };

  const gradientStops = visualSpec.gradientStops;
  const gradientStart = Array.isArray(gradientStops) && gradientStops.length
    ? gradientStops[0]?.color ?? gradientStops[0]
    : colors.surface;
  const gradientEnd = Array.isArray(gradientStops) && gradientStops.length > 1
    ? gradientStops[gradientStops.length - 1]?.color ?? gradientStops[gradientStops.length - 1]
    : colors.ink;

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    colorVector(gradientStart, colors.surface),
    colorVector(gradientEnd, colors.ink),
    smoothstep(0.05, 0.95, uv().y),
  );
  const backdropGeometry = new PlaneGeometry(7, 6, 1, 1);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const rimLight = new PointLight(colors.accent, 0.7, 7, 2);
  rimLight.position.set(2.8, 1.8, 2.2);
  root.add(rimLight);

  const fillLight = new PointLight(colors.paper, 0.35, 6, 2);
  fillLight.position.set(-2.5, -1.2, 1.4);
  root.add(fillLight);

  const row = new Group();
  row.name = 'interactive-features-row';
  root.add(row);

  const panelGeometry = new BoxGeometry(4.9, 0.82, 0.14, 4, 4, 2);
  const panelMaterial = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.64,
    metalness: 0.42,
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'machined-row-panel';
  panel.position.z = 0.05;
  row.add(panel);
  ownedGeometries.push(panelGeometry);
  ownedMaterials.push(panelMaterial);

  const innerGeometry = new BoxGeometry(4.62, 0.64, 0.035, 2, 2, 1);
  const innerMaterial = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.72,
    metalness: 0.2,
  });
  const inner = new Mesh(innerGeometry, innerMaterial);
  inner.name = 'row-inner-surface';
  inner.position.set(0, 0, 0.14);
  row.add(inner);
  ownedGeometries.push(innerGeometry);
  ownedMaterials.push(innerMaterial);

  const dividerGeometry = new BoxGeometry(4.35, 0.012, 0.018, 1, 1, 1);
  const dividerMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.2,
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.name = 'subtle-divider';
  divider.position.set(0, -0.27, 0.19);
  row.add(divider);
  ownedGeometries.push(dividerGeometry);
  ownedMaterials.push(dividerMaterial);

  const edgeGeometry = new BoxGeometry(0.035, 0.68, 0.028, 1, 1, 1);
  const edgeMaterial = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.18,
  });
  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.name = 'accent-focus-edge';
  edge.position.set(-2.26, 0, 0.2);
  row.add(edge);
  ownedGeometries.push(edgeGeometry);
  ownedMaterials.push(edgeMaterial);

  const imageGeometry = new PlaneGeometry(1.2, 0.66, 64, 64);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
  });
  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'parallax-depth-image';
  image.position.set(1.58, 0, 0.22);
  row.add(image);
  ownedGeometries.push(imageGeometry);
  ownedMaterials.push(imageMaterial);

  let imageTexture;
  let depthTexture;

  const loadAssets = async () => {
    if (config.imageUrl) {
      try {
        imageTexture = await ctx.textureLoader.loadTexture(config.imageUrl);
        if (disposed) {
          imageTexture.dispose?.();
        } else {
          imageTexture.colorSpace = THREE.SRGBColorSpace ?? imageTexture.colorSpace;
          imageMaterial.colorNode = sampleTexture(imageTexture, uv());
          imageMaterial.needsUpdate = true;
          loadedTextures.push(imageTexture);
        }
      } catch {
        // The designed paper-toned fallback remains visible.
      }
    }

    if (config.depthMapUrl) {
      try {
        depthTexture = await ctx.textureLoader.loadTexture(config.depthMapUrl);
        if (disposed) {
          depthTexture.dispose?.();
        } else {
          const depth = sampleTexture(depthTexture, uv()).r;
          imageMaterial.positionNode = positionLocal.add(
            normalLocal.mul(depth.sub(0.5).mul(0.12)),
          );
          imageMaterial.needsUpdate = true;
          loadedTextures.push(depthTexture);
        }
      } catch {
        // The tessellated plane remains a stable fallback.
      }
    }
  };

  void loadAssets();

  const entrance = gsap.timeline({ paused: false });
  entrance.from(row.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  entrance.from(
    row.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.9,
      ease: 'power4.out',
    },
    '<0.05',
  );
  timelines.push(entrance);

  const hoverLift = gsap.timeline({ paused: true });
  hoverLift.to(row.position, {
    y: 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });
  hoverLift.to(
    row.rotation,
    {
      z: -0.018,
      duration: 0.3,
      ease: 'power2.out',
    },
    '<',
  );
  hoverLift.to(
    edgeMaterial,
    {
      opacity: 0.72,
      duration: 0.3,
      ease: 'power2.out',
    },
    '<',
  );
  timelines.push(hoverLift);

  const parallax = gsap.timeline({ paused: true });
  parallax.to(image.position, {
    x: 1.68,
    duration: 0.45,
    ease: 'power2.out',
  });
  timelines.push(parallax);

  root.userData.handlers = {
    hover(active) {
      if (disposed) return;
      const isActive = active === true || active?.active === true || active?.type === 'enter';
      if (isActive) {
        hoverLift.play();
        parallax.play();
      } else {
        hoverLift.reverse();
        parallax.reverse();
      }
    },

    click() {
      if (disposed) return;
      gsap.timeline()
        .to(row.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'power2.out',
        })
        .to(row.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.34,
          ease: 'back.out(2)',
        });
      ctx.emit('hub-features.select', {
        node: config.id ?? 'hub-features-card',
        checkoutUrl: config.data?.checkoutUrl ?? config.checkoutUrl,
      });
    },

    focus(active) {
      if (disposed) return;
      gsap.to(edgeMaterial, {
        opacity: active ? 1 : 0.18,
        duration: 0.2,
        ease: 'power2.out',
      });
    },
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline.kill();
    for (const cleanup of primitiveCleanups) cleanup?.();

    for (const textureResource of loadedTextures) textureResource.dispose?.();
    for (const geometry of ownedGeometries) geometry.dispose?.();
    for (const material of ownedMaterials) material.dispose?.();

    root.clear();
  };

  return root;
}
